-- Old FEDER operations remain separate from consolidated PAIP award cases.
create table public.paid_aragon_legacy_operations (
 operation_code text primary key,
 year smallint not null check(year between 2017 and 2020),
 record jsonb not null check(jsonb_typeof(record)='object'),
 check(record ?& array['id','operation_code','year','record_type','status','granted_amount','eligible_budget','score']),
 check(record @> '{"record_type":"feder_operation","status":"operacion_feder","granted_amount":null,"eligible_budget":null,"score":null}'::jsonb),
 check(record->>'operation_code'=operation_code),
 check((record->>'year')::integer=year)
);
comment on table public.paid_aragon_legacy_operations is 'Partial FEDER operation coverage for 2017–2020. Operation costs are not PAIP grants; no inferred award result or score.';
alter table public.paid_aragon_legacy_operations enable row level security;
revoke all on public.paid_aragon_legacy_operations from public,anon,authenticated;
grant select on public.paid_aragon_legacy_operations to authenticated;
grant all on public.paid_aragon_legacy_operations to service_role;
create policy paid_aragon_legacy_read on public.paid_aragon_legacy_operations for select to authenticated
using ((select private.current_user_is_active()) and exists (
 select 1 from public.calls c join public.user_call_access a on a.call_id=c.id
 where c.code='PAID-ARAGON' and c.status='active' and a.user_id=(select auth.uid())
));
